-- Provisional 102 sellable products; apply after phase1c_buildable_master.sql.
-- Disposable PostgreSQL fixture; commercial values await sourcing and freeze.
SET search_path TO deal_desk, public;
DO $catalogue$
BEGIN
  IF (SELECT count(*) FROM products) <> 156 OR
     (SELECT count(*) FROM products WHERE is_sellable) <> 120 OR
     (SELECT count(*) FROM products WHERE fulfillment_mode = 'component') <> 36 OR
     (SELECT count(DISTINCT fulfillment_mode) FROM products WHERE is_sellable) <> 5
  THEN RAISE EXCEPTION 'Provisional catalogue coverage differs'; END IF;
END
$catalogue$;
